gUX(){return"\u063a\u064a\u0627\u0628"},
gafG(){return"\u0639\u0644\u0649 \u0627\u0644\u0628\u0627\u0635"},
gafz(){return"\u0648\u0635\u0644\u0648\u0627"},
gafK(){return"\u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u0631\u0643\u0648\u0628"},
gafI(){return"\u0628\u062f\u0623\u062a"},
gafF(){return"\u0627\u0646\u062a\u0647\u062a"},
gafB(){return"\u0627\u0644\u062a\u0623\u062e\u064a\u0631 \u0647\u0646\u0627 \u062a\u0623\u062e\u064a\u0631 \u0628\u062f\u0621 \u0631\u062d\u0644\u0629 \u0627\u0644\u0635\u0628\u0627\u062d \u0639\u0646 \u0645\u0648\u0639\u062f \u0627\u0644\u0631\u0643\u0648\u0628 \u0627\u0644\u0645\u0633\u062c\u0644 \u0648\u0642\u062a \u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0631\u062d\u0644\u0629\u060c \u0645\u0634 \u062a\u0623\u062e\u064a\u0631 \u0648\u0635\u0648\u0644 \u0627\u0644\u0645\u062f\u0631\u0633\u0629. \u0627\u0644\u0631\u062d\u0644\u0627\u062a \u0627\u0644\u0642\u062f\u064a\u0645\u0629 \u0623\u0648 \u0627\u0644\u0639\u0648\u062f\u0629 \u0642\u062f \u0644\u0627 \u064a\u0643\u0648\u0646 \u0644\u0647\u0627 \u0645\u0648\u0639\u062f \u0645\u0642\u0627\u0631\u0646\u0629."},
gafC(){return"\u062a\u0623\u062e\u064a\u0631 \u0627\u0644\u0628\u062f\u0621: \u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0648\u0639\u062f \u0645\u0642\u0627\u0631\u0646\u0629 \u0645\u062d\u0641\u0648\u0638"},
